INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4283024, 614020, 12253, '<td valign="top">Congrat''s Deb--I''ve not been paying attention to challenge results, so missed that you got top 10!  Way to go!</td>', 'Congrat''s Deb--I''ve not been paying attention to challenge results, so missed that you got top 10!  Way to go!', '2007-12-02 15:41:49.000000', NULL, 0),
(4285314, 615104, 67697, '<td valign="top">You have so many fascinating people to photograph.  If this guy were in my town, he''d have been quickly hauled off to jail lol.  I love how it looks almost as if he is supposed to be a permanent part of that piece he is standing on.  Very cool.  Congrats on the top 20!</td>', 'You have so many fascinating people to photograph.  If this guy were in my town, he''d have been quickly hauled off to jail lol.  I love how it looks almost as if he is supposed to be a permanent part of that piece he is standing on.  Very cool.  Congrats on the top 20!', '2007-12-03 10:31:47.000000', NULL, 0),
(4286174, 614996, 67697, '<td valign="top">lol how funny - did they even notice you taking a picture?  that looks like a diner!  open at 4 am and having beer?  I assume you were there having coffee hahaahah</td>', 'lol how funny - did they even notice you taking a picture?  that looks like a diner!  open at 4 am and having beer?  I assume you were there having coffee hahaahah', '2007-12-03 16:33:12.000000', NULL, 0),
(4286522, 614969, 70036, '<td valign="top"><b>Welcome from the Critique Club :)</b> <br/> <br/>Concept<br/> <br/>I cannot say that this really fits the challenge.  Even the long title does not really successfully shoe horn it in.<br/> <br/>First Impressions<br/> <br/>My very first impression is ''I wish I could see the model better''.  I fell like I am in a dimly lit room at dusk and everything is murky.   I think there is much potential to this image, but it seems lost in the low-lit, noisy image.   Her skin tone appears to be lost amongst the image noise.  It cries out for contrast and sharper focus.<br/> <br/>Composition<br/> <br/>The pose is interesting, but perhaps the focal length seems to magnify the model''s butt a bit.   There is a drama and movement to the pose which I like.<br/> <br/>Color<br/> <br/>The color balance is interesting but in combination with the lack of image sharpness seems to detract from the model''s skin tone.<br/> <br/>I think this image has potential, but I am having a hard time getting past the image noise and lack of sharpness to fall in love with this one.  I keep wanting to see it in black white with enough contrast so I do not have to work so hard to appreciate what I am looking at.<br/> <br/>If you have any questions, please feel free to use the PM system to contact me.<br/> <br/>Ken<br/></td>', 'Welcome from the Critique Club :)  Concept I cannot say that this really fits the challenge.  Even the long title does not really successfully shoe horn it in. First Impressions My very first impression is ''I wish I could see the model better''.  I fell like I am in a dimly lit room at dusk and everything is murky.   I think there is much potential to this image, but it seems lost in the low-lit, noisy image.   Her skin tone appears to be lost amongst the image noise.  It cries out for contrast and sharper focus. Composition The pose is interesting, but perhaps the focal length seems to magnify the model''s butt a bit.   There is a drama and movement to the pose which I like. Color The color balance is interesting but in combination with the lack of image sharpness seems to detract from the model''s skin tone. I think this image has potential, but I am having a hard time getting past the image noise and lack of sharpness to fall in love with this one.  I keep wanting to see it in black white with enough contrast so I do not have to work so hard to appreciate what I am looking at. If you have any questions, please feel free to use the PM system to contact me. Ken', '2007-12-03 18:39:18.000000', NULL, 0),
(4286559, 614349, 81301, '<td valign="top">awesome shot! very WELL deserved a ribbon!!!<br/> <br/></td>', 'awesome shot! very WELL deserved a ribbon!!! ', '2007-12-03 18:54:22.000000', NULL, 0),
(4286772, 614870, 66267, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by rcpmac:</b></div><hr/><i> <table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Noel_ZH:</b></div><hr/><i> Awesome concept, think the b/w failed somewhat, white ball is not white, etc.. 6 </i></td></tr></table> <br/>Perhaps your screen needs calibration.  It appears white on my MacBook Pro. </i></td></tr></table> <br/> <br/>It''s far from white, it''s a pretty neutral grey.<br/><br/><i>Message edited by author 2007-12-03 20:15:48.</i></td>', 'Originally posted by rcpmac: Originally posted by Noel_ZH: Awesome concept, think the b/w failed somewhat, white ball is not white, etc.. 6  Perhaps your screen needs calibration.  It appears white on my MacBook Pro.   It''s far from white, it''s a pretty neutral grey.', '2007-12-03 20:14:48.000000', '2007-12-03 20:15:48.000000', 0),
(4288165, 614967, 3746, '<td valign="top">Hmmm, someone likes your images, the same person gave you a glowing comment on your other challenge entry, and you got a ten on both occasions. weird huh, hope no one looks into this too deeply.</td>', 'Hmmm, someone likes your images, the same person gave you a glowing comment on your other challenge entry, and you got a ten on both occasions. weird huh, hope no one looks into this too deeply.', '2007-12-04 11:54:16.000000', NULL, 0),
